export const spisiSearch: { slug: string; chunks: { text: string; headingId: string; headingText: string }[] }[] = [{"slug":"Agej-2-7-zelja-svih-naroda","chunks":[{"text":"U hebrejskom tekstu Ageja 2:7 javlja se koren hmd, koji odgovara arapskom korenu h m d, od kojeg dolazi ime Muhammed, u značenju hvaljeni ili najhvaljeniji. Ser Godfri Higins navodi da je Muhammed kod Ageja izričito najavljen i po imenu, te da tu nema umetanja niti načina da se taj jasan tekst zaobiđe.","headingId":"","headingText":""},{"text":"Tekst proročanstva Agej 2:7 I zatrešću sve narode, i doći će željeni svim narodima, i napuniću ovaj dom slavom, govori Gospod nad vojskama.","headingId":"tekst-prorocanstva","headingText":"Tekst proročanstva"},{"text":"Hebrejski koren hmd U hebrejskom tekstu javlja se koren hmd, odnosno חמד, koji se prevodi kao željeni, a nosi značenje hvaljenog, odnosno onoga koga svi narodi žele i hvale. Taj hebrejski koren odgovara arapskom korenu h m d, od kojeg dolazi ime Muhammed, u značenju onaj koji je hvaljen, odnosno najhvaljeniji.","headingId":"hebrejski-koren-hmd","headingText":"Hebrejski koren hmd"},{"text":"Svedočanstva nemuslimanskih istraživača Ovde je Muhammed izričito najavljen kod Ageja, i to po imenu. Ovde nema umetanja. Nema načina da se izbegne ovaj jasan tekst i njegovo značenje. Izvor: ser Godfri Higins. Godfrey Higgins, Anacalypsis, tom 1, str. 679. M. A. Jusuf upućuje na to da hebrejska slova na tom mestu daju oblik hamd, odnosno hmd, prema samom hebrejskom tekstu. M. A. Youssef, The Dead Sea Scrolls, str. 110. Na istu vezu upućuje se i u časopisu Notes and Queries and Historic Magazine. Notes and Queries and Historic Magazine, tom 23, str. 122.","headingId":"svedocanstva-nemuslimanskih-istrazivaca","headingText":"Svedočanstva nemuslimanskih istraživača"}]},{"slug":"Da-li-je-Ibrahim-bio-Jevrejin","chunks":[{"text":"Reč Hebrej razlikuje se od reči Jevrejin i po poreklu i po tvorbi i po značenju. U celoj Bibliji ne postoji nijedno mesto na kojem se za Ibrahima kaže da je bio Jevrejin. Uz to, ako jevrejstvo kao vera počinje sa Musaom, onda Ibrahim, koji mu prethodi, ne može biti Jevrejin. To priznaju i jevrejski i hrišćanski izvori.","headingId":"","headingText":""},{"text":"Primedba Pojedini misionari tvrde da je Ibrahim bio Jevrejin, a ne musliman, kako navodi Kur'an, i to iznose kao navodnu istorijsku grešku.","headingId":"primedba","headingText":"Primedba"},{"text":"Prvo Hebrej nije isto što i Jevrejin Reč Hebrej razlikuje se od reči Jevrejin i po poreklu i po tvorbi i po značenju. Hebreji su jedna od grana semitske porodice. Njihovo ime vezuje se za Ebera, jednog od Ibrahimovih predaka. U celoj Bibliji, u oba njena zaveta, ne postoji nijedno mesto na kojem se za Ibrahima kaže da je bio Jevrejin.","headingId":"prvo-hebrej-nije-isto-sto-i-jevrejin","headingText":"Prvo - Hebrej nije isto što i Jevrejin"},{"text":"Drugo hronološka nemogućnost Ako se smatra da jevrejstvo kao vera počinje sa Musaom, mir neka je na njega, kako onda Ibrahim može biti Jevrejin? I jevrejski i hrišćanski izvori slažu se da Ibrahim prethodi jevrejstvu. Sajt jewfaq.org navodi: „Pogrešno je Ibrahima, Ishaka i Jakova smatrati Jevrejima, jer se naziv jevrejski i judaizam nije primenjivao na taj narod.\" jewfaq.org. Isto navodi i hrišćanski sajt rcg.org. rcg.org.","headingId":"drugo-hronoloska-nemogucnost","headingText":"Drugo - hronološka nemogućnost"},{"text":"Treće Ibrahimova vera bila je predanost Bogu Sura Ali Imran 3:67 Ibrahim nije bio ni Jevrejin ni hrišćanin, već pravi vernik, predan Bogu, i nije bio od mnogobožaca. Sura El Bekara 2:131 Kada mu je Gospodar njegov rekao: Budi predan! On je odgovorio: Ja sam predan Gospodaru svetova. To se poklapa i sa Postanjem 17:1, gde se u Onkelosovom targumu za Ibrahima koristi izraz šelim, u značenju potpun, odnosno posvećen. Postanje 17:1 Hodi preda mnom i budi pošten. U proširenom engleskom prevodu to mesto glasi: hodi preda mnom sa čestitošću, znajući da si uvek u Mojoj prisutnosti, i budi besprekoran i potpun u pokornosti Meni.","headingId":"trece-ibrahimova-vera-bila-je-predanost-bogu","headingText":"Treće - Ibrahimova vera bila je predanost Bogu"},{"text":"Svedočanstva Rabin Tovija Singer naveo je da je poslanik Ibrahim bio musliman u smislu potpune predanosti Bogu. Rabin Tovija Singer. Jedan crkveni sajt priznao je da istorija islamskog naroda počinje sa poslanikom Ibrahimom i njegovim potomcima. puconline.org. Izvorni tekst na ovom mestu iznosi i niz tvrdnji o namernim izmenama biblijskog teksta, sa brojkama o razlikama između samarićanskog i masoretskog Petoknjižja. Te tvrdnje su ovde izostavljene, jer izvorni tekst za njih ne navodi proverljive izvore, a sam argument o Ibrahimu na njima i ne počiva.","headingId":"svedocanstva","headingText":"Svedočanstva"}]},{"slug":"Dodatne-napomene-o-Poslaniku-u-Bibliji","chunks":[{"text":"Ovo je zbirka kraćih napomena i rukopisnih nalaza, a ne zaokružena rasprava. Obuhvata Avakuma 3:3 i pomen hvale, Psalam 72 i darove Arapa, Isaiju 42:11 i Kedara, koptske rukopise koji Kedara poistovećuju sa Kurejšijama, kao i tumačenje Ibn Ezre koji bunar Lahaj Roi poistovećuje sa Zemzemom. Napomene koje slede prenose se onako kako ih izvorni tekst donosi, u obliku kratkih beleški uz pojedine rukopise. Za veći deo njih izvorni tekst ne navodi potpune bibliografske podatke.","headingId":"","headingText":""},{"text":"Avakum 3:3 Avakum 3:3 Bog dođe od Temana i Svetac s gore Farana; slava Njegova pokri nebesa i zemlja se napuni hvale Njegove. Izvorni tekst tu skreće pažnju na spomen hvale kojom se zemlja puni.","headingId":"avakum-33","headingText":"Avakum 3:3"},{"text":"Psalam 72 Iz tog psalma izdvajaju se tri iskaza: 1. Da su Mu svi Arapi doneli darove i danak. 2. Da je siromahe izbavio od nasilnih sila. 3. Da je sva zemlja ispunjena slavom.","headingId":"psalam-72","headingText":"Psalam 72"},{"text":"Isaija 42:11 Isaija 42:11 Neka podignu glas pustinja i gradovi njeni, sela gde stanuje Kedar. Rukopisi koptske pravoslavne patrijaršije Kedara tumače kao Kurejšije, pleme iz kojeg potiče Muhammed ﷺ. Rukopisi koptske pravoslavne patrijaršije.","headingId":"isaija-4211","headingText":"Isaija 42:11"},{"text":"Rukopis oca Germanusa Verzija oca Germanusa, biskupa manastira Svete Katarine, iz trinaestog veka, iz 1228. godine, sadrži belešku uz Isaiju. Rukopis oca Germanusa, manastir Svete Katarine, 1228. Sličan zapis navodi se i uz Isaiju 5:1, u koptskom rukopisu iz sedamnaestog veka. Koptski rukopis, oznaka cop 8 10, sedamnaesti vek.","headingId":"rukopis-oca-germanusa","headingText":"Rukopis oca Germanusa"},{"text":"Postanje 16:14 i bunar Lahaj Roi Postanje 16:14 Toga radi zove se studenac onaj studenac Živoga koji me vidi. Jevrejski rabin Ibn Ezra taj bunar poistovećuje sa Zemzemom u Meki. Ibn Ezra, uz Postanje 16:14.","headingId":"postanje-1614-i-bunar-lahaj-roi","headingText":"Postanje 16:14 i bunar Lahaj-Roi"},{"text":"Jovan 16 Upućuje se i na Jovana 16 i na pitanje Zagovornika, o čemu je opširnije pisano u posebnom tekstu.","headingId":"jovan-16","headingText":"Jovan 16"},{"text":"Rabin Netanel iz Fajuma Srednjovekovni učenjak, rabin Netanel iz Fajuma, Poslanika ﷺ nazivao je Pravednim. Rabin Netanel iz Fajuma.","headingId":"rabin-netanel-iz-fajuma","headingText":"Rabin Netanel iz Fajuma"}]},{"slug":"Hodocasce-u-Izlasku-5-1","chunks":[{"text":"U Izlasku 5:1 javlja se hebrejski oblik וְיָחֹגּוּ, izveden iz korena hagag. Strongov rečnik, pod brojem H2287, taj koren prevodi kao obaviti hodočašće, a Braunov rečnik ga izričito upoređuje sa arapskim glagolom u značenju uputiti se ka predmetu poštovanja i obaviti hodočašće u Meku. Više savremenih engleskih prevoda to mesto i prevodi rečju hodočašće.","headingId":"","headingText":""},{"text":"Tekst Izlazak 5:1 A posle izađoše Mojsije i Aron pred faraona, i rekoše mu: Ovako veli Gospod Bog Izrailjev: Pusti narod moj da mi praznuju praznik u pustinji. Izraz o kojem je reč jeste וְיָחֹגּוּ.","headingId":"tekst","headingText":"Tekst"},{"text":"Rečničke odrednice Strongov rečnik, pod brojem H2287, taj koren određuje u značenju obaviti hodočašće. Strong's Dictionary, H2287. Braunov rečnik navodi: חָגַג, glagol: obaviti hodočašće, održati hodočasnički praznik; arapski: uputiti se ka predmetu poštovanja, obaviti hodočašće u Meku. Izvor: Brown Driver Briggs. Brown Driver Briggs Lexicon, odrednica חָגַג. Uporedni koren, pod brojem H2328, glasi חוּג i znači načiniti krug. Strong's Dictionary, H2328.","headingId":"recnicke-odrednice","headingText":"Rečničke odrednice"},{"text":"Savremeni prevodi 1. ISV: „Pusti moj narod da mi obavi hodočašće u pustinji.\" 2. TLB: „Kaže: Pusti moj narod, jer moraju obaviti sveto hodočašće u pustinju, radi verskog praznika, da Mi tamo iskažu obožavanje.\" 3. NET: „Pusti moj narod da Mi održi hodočasnički praznik u pustinji.\"","headingId":"savremeni-prevodi","headingText":"Savremeni prevodi"},{"text":"Kruženje kao obred Jedino mesto na Zemlji na kojem ljudi hodočaste i obožavanje Musaovom Bogu iskazuju kruženjem, odnosno tavafom, jeste Časna Kaba.","headingId":"kruzenje-kao-obred","headingText":"Kruženje kao obred"},{"text":"Predaje o Musau i telbiji Allahov Poslanik ﷺ prošao je pored doline El Ezrek i rekao: Koja je ovo dolina? Rekli su: Ovo je dolina El Ezrek. Rekao je: Kao da vidim Musaa, mir neka je na njega, kako silazi sa prevoja i uči telbiju Allahu. Izvor: Abdullah ibn Abbas. Sahih Muslim, br. 166. Što se tiče Musaa, on je tamnoput čovek kovrdžave kose, jaše crvenu devu sa ularom. Kao da ga gledam kako silazi u dolinu učeći telbiju. Izvor: Sahih Buhari. Sahih Buhari. Temelje Kabe podigli su Ibrahim i njegov sin Ismail, mir neka je na njih obojicu, a Allah je poslanicima dozvolio da obave hadž odazivajući se Ibrahimovom pozivu.","headingId":"predaje-o-musau-i-telbiji","headingText":"Predaje o Musau i telbiji"},{"text":"Odeća Izlazak 33:5 6 Skinite nakit svoj sa sebe, i znaću šta ću činiti s vama. I poskidaše sa sebe sinovi Izrailjevi nakit svoj kod gore Horiva. Prošireni prevod to mesto donosi rečima: „Skinite sav svoj nakit, i odlučiću šta ću sa vama. I narod Izrailjev skinuo je svoj nakit kod gore Sinaj.\" Muslimana u ihramima pokrivaju samo dva dela odeće. Komentar jedne hrišćanske Biblije iz 1833. godine navodi: Tako su se sinovi Izrailjevi skinuli sa svoje odeće i nakita. Taj običaj bio je poznat u prošlosti, a i danas se održava na Istoku, tokom hodočasničkih obreda muslimana u Meku. Izvor: komentar Biblije iz 1833. Komentar hrišćanske Biblije, 1833.","headingId":"odeca","headingText":"Odeća"},{"text":"Svedočanstvo rabina Tovije Singera Muslimani čvrsto veruju da je Ibrahim, mir neka je na njega, bio musliman. Muslimani obožavaju jednog istinskog Boga. Izvor: rabin Tovija Singer. Rabin Tovija Singer. Izvorni tekst na jednom mestu iznosi i tvrdnju o namernoj izmeni te reči od strane prepisivača. Ta tvrdnja ovde nije preneta, jer sam argument počiva na rečničkim odrednicama i na savremenim prevodima, koji tu reč i bez toga prevode kao hodočašće.","headingId":"svedocanstvo-rabina-tovije-singera","headingText":"Svedočanstvo rabina Tovije Singera"}]},{"slug":"Isaija-29-12-i-nepismeni","chunks":[{"text":"Isaija 29:12 govori o knjizi koja se predaje onome ko nije učen, sa rečima „pročitaj ovo\", na šta on odgovara da nije učen. Hebrejska reč קְרָא, kara, znači čitati, a ne pisati. To se poredi sa predajom o prvom susretu u pećini Hira, gde na naredbu „Čitaj\" Poslanik ﷺ odgovara da ne zna da čita.","headingId":"","headingText":""},{"text":"Tekst Isaija 29:12 A kad daju knjigu onome koji ne zna knjige govoreći: Čitaj to; on reče: Ne znam knjige. U engleskom prevodu King James to glasi: „And the book is delivered to him that is not learned, saying, Read this, I pray thee: and he saith, I am not learned.\"","headingId":"tekst","headingText":"Tekst"},{"text":"Hebrejska reč U hebrejskom tekstu javlja se reč קְרָא, koja se izgovara kara i znači čitanje, a ne pisanje.","headingId":"hebrejska-rec","headingText":"Hebrejska reč"},{"text":"Poređenje sa predajom o pećini Hira Došao mu je melek i rekao: Čitaj. Rekao je: Ja ne znam čitati. Izvor: Sahih Buhari, od Aiše, radijallahu anha. Sahih Buhari, predaja od Aiše o početku objave. Osama Poslanika ﷺ u pećini Hira, način na koji mu je Kur'an objavljivan, i to što je bio nepismen, poklapaju se sa opisom iz Isaije 29:12. Izvorni tekst na ovom mestu iznosi i tvrdnju da grčki oblik iz rukopisa Isaije izvorno glasi „u pećini Hira\", i da je naknadnim dodavanjem jednog slova promenjen u „ruke\". Ta tvrdnja ovde nije preneta, jer grčka reč χεῖρας u standardnim rečnicima znači ruke, a za tvrdnju o namernoj izmeni nema paleografske potvrde. Sama podudarnost opisa iz Isaije 29:12 sa predajom","headingId":"poredjenje-sa-predajom-o-pecini-hira","headingText":"Poređenje sa predajom o pećini Hira"},{"text":"o pećini Hira ne zavisi od te tvrdnje.","headingId":"poredjenje-sa-predajom-o-pecini-hira","headingText":"Poređenje sa predajom o pećini Hira"}]},{"slug":"Isaija-42-1-i-oblik-ahmad","chunks":[{"text":"Masoretski tekst Isaije 42:1 ima אֶתְמָךְ בּוֹ, dok se predlaže izvorno čitanje אַחְמַד. Ta dva oblika grafički su bliska. Koren תמך, prema Jastrovom rečniku, znači podupreti, poduprti se, pritisnuti, i nema veze sa naklonošću. Matej 12:18 to mesto ipak prenosi grčkom rečju agapetos, ljubljeni, koja se iz tog korena ne može izvesti, nego iz korena חמד.","headingId":"","headingText":""},{"text":"Kur'anski osnov Sura Es Saff 61:6 O sinovi Israilovi, ja sam vam Allahov poslanik da vam potvrdim pre mene objavljeni Tevrat i da vam donesem radosnu vest o poslaniku čije je ime Ahmed, koji će posle mene doći.","headingId":"kuranski-osnov","headingText":"Kur'anski osnov"},{"text":"Tekst Isaije Isaija 42:1 Evo sluge mog, koga podupirem, izabranika mog, koji je mio duši mojoj. Masoretski tekst na tom mestu ima עַבְדִּי אֶתְמָךְ בּוֹ בְּחִירִי, dok se kao izvorno čitanje predlaže עַבְדִּי אַחְמַד בְּחִירִי.","headingId":"tekst-isaije","headingText":"Tekst Isaije"},{"text":"Značenje korena tamah Jastrov rečnik pokazuje da koren תמך znači podupreti, ležati ispod, počivati na nečemu, pritisnuti, i da nema veze sa naklonošću ili ljubavlju. Jastrow's Dictionary, odrednica תמך.","headingId":"znacenje-korena-tamah","headingText":"Značenje korena tamah"},{"text":"Kako to mesto prenosi Matej Matej 12:18 Gle, sluga moj, koga sam izabrao, ljubazni moj, koji je po volji duše moje. Matej to mesto prenosi grčkom rečju ἀγαπητός, agapetos, u značenju ljubljeni. Ta reč se ne može izvesti iz korena תמך, koji znači podupirati, nego iz korena חמד, koji nosi značenje voljenog i hvaljenog, a to je koren imena Ahmed.","headingId":"kako-to-mesto-prenosi-matej","headingText":"Kako to mesto prenosi Matej"},{"text":"Grafička bliskost Oblici אתמך i אחמד grafički su bliski, pa je prepisivačka zamena u okviru tekstualne kritike moguća pojava.","headingId":"graficka-bliskost","headingText":"Grafička bliskost"},{"text":"Obrazac u Bibliji Na svakom drugom mestu na kojem se izraz „sluga moj\" javlja uz „izabranik moj\", uz njih stoji i ime poslanika. Isaija 42:1 jedino je mesto na kojem imena nema, nego stoji taj oblik.","headingId":"obrazac-u-bibliji","headingText":"Obrazac u Bibliji"},{"text":"Svici sa Mrtvog mora Svici sa Mrtvog mora na tom mestu imaju oblik אתמוכה, koji se predlaže kao iskvarenje aramejskih oblika poput אחמודה.","headingId":"svici-sa-mrtvog-mora","headingText":"Svici sa Mrtvog mora"},{"text":"Poređenje sa Agejem 2:7 Agej 2:7 I doći će željeni svim narodima. Tu se javlja oblik חמדת, iz korena חמד, koji Septuaginta prenosi rečju ἐκλεκτά, u značenju izabrani.","headingId":"poredjenje-sa-agejem-27","headingText":"Poređenje sa Agejem 2:7"},{"text":"Svedočanstvo Ka'ba el Ahbara Ka'b el Ahbar prenosi da je u rukopisima Tevrata našao: Ahmed el Muhtar, on nije ni grub ni osoran, niti viče po pijacama, niti zlo uzvraća zlim, nego prašta i oprašta. Izvor: Ka'b el Ahbar. Predaja od Ka'ba el Ahbara. Izvorni tekst i sam priznaje jedno otvoreno pitanje: zamenicu בו, „njega\", u masoretskom čitanju treba objasniti. Nude se dve mogućnosti, da je reč o zabuni sa oblikom בן, „sin\", ili o naknadnom prepisivačkom dodatku radi gramatičke celovitosti. Sam predlog izvornog čitanja ostaje, dakle, rekonstrukcija, a ne potvrđen rukopisni nalaz.","headingId":"svedocanstvo-kaba-el-ahbara","headingText":"Svedočanstvo Ka'ba el-Ahbara"}]},{"slug":"Isaija-42-i-Kedar","chunks":[{"text":"Isaija 42 govori o Božijem sluzi koji će pravdu doneti narodima, a jedanaesti ajet izričito spominje naselja u kojima živi Kedar i stanovnike Sele. Biblijski rečnici Kedar poistovećuju sa arapskim pustinjskim plemenima, a Filip Šaf u svom rečniku navodi da predanje Kedara čini jednim od predaka Muhammeda ﷺ.","headingId":"","headingText":""},{"text":"Tekst Isaija 42:1 Evo sluge mog, koga podupirem, izabranika mog, koji je mio duši mojoj; metnuću duh svoj na njega, sud narodima javljaće. Isaija 42:11 Neka podignu glas pustinja i gradovi njeni, sela gde stanuje Kedar; neka kliču koji žive po stenama, neka viču s vrh gora.","headingId":"tekst","headingText":"Tekst"},{"text":"Ko je Kedar Postanje 25:16 18 To su sinovi Ismailovi, i to su im imena po selima i gradovima njihovim, dvanaest knezova nad plemenima svojim. A življahu od Evila do Sura prema Egiptu, kako se ide u Asiriju. Kedar i Sela prepoznaju se kao arapske oblasti. Komentari Džejmisona, Fauseta i Brauna, Gilovo tumačenje, kao i rečnik Brauna, Drajvera i Brigsa, Kedar poistovećuju sa Arabijom Desertom i nomadskim Arapima. Jamieson Fausset Brown; Gill's Exposition; Brown Driver Briggs Lexicon. To pleme izgleda da je bilo jedno od najistaknutijih među svim ismailovskim plemenima, pa zato rabini tim imenom nazivaju Arape uopšte. Izvor: Smitov biblijski rečnik, odrednica Kedar. Smith's Bible Dictionary, odrednica Kedar. Filip Šaf u svom rečniku navodi: „Predanje Kedara čini jednim od","headingId":"ko-je-kedar","headingText":"Ko je Kedar"},{"text":"predaka Muhammeda.\" Philip Schaff, Dictionary. Strongov rečnik, pod brojem H2341, Evilu opisuje kao pokrajinu koju naseljavaju Ismailovi potomci, smeštenu na Arapskom poluostrvu. Strong's Dictionary, H2341.","headingId":"ko-je-kedar","headingText":"Ko je Kedar"},{"text":"Duhovni preokret Isaija 42:11 17 opisuje napuštanje obožavanja kipova i okretanje jednom Bogu. Jedan koptski pravoslavni rukopis Kedar poistovećuje sa Kurejšijama. Koptski pravoslavni rukopis.","headingId":"duhovni-preokret","headingText":"Duhovni preokret"},{"text":"Odgovor na hrišćanski prigovor Prigovor se poziva na Mateja 12:15 23, gde se to mesto primenjuje na Isaa. Odgovara se sledećim: 1. Taj navod predstavlja tumačenje pisca Jevanđelja po Mateju, čije autorstvo nije poznato. 2. Kontekst tog odlomka obuhvata samo Israilćane, a ne narode uopšte, dok Isaija 42 izričito govori o narodima. 3. Stari zavet odbacuje učenje o nasleđenom grehu i o zamenskom iskupljenju. Ponovljeni zakon 24:16 Neka ne ginu očevi za sinove ni sinovi za očeve; svaki za svoj greh neka gine. Jezekilj 18:20 Duša koja greši ona će umreti; sin neće nositi bezakonja očevog niti će otac nositi bezakonja sinovljevog.","headingId":"odgovor-na-hriscanski-prigovor","headingText":"Odgovor na hrišćanski prigovor"},{"text":"Uslovi iz Isaije 53:10 Isaija 53:10 Kad položi dušu svoju u prinos za greh, videće natražje. Taj uslov iziskuje potomstvo i dug život.","headingId":"uslovi-iz-isaije-5310","headingText":"Uslovi iz Isaije 53:10"},{"text":"Rašijevo tumačenje Raši, uz Isaiju 52:13, navodi: „Gle, na kraju dana, sluga moj Jakov će napredovati\", čime slugu poistovećuje sa Izrailjem. Raši, uz Isaiju 52:13. Raši, uz Ponovljeni zakon 33:2, navodi: „Otišao je tamo i ponudio sinovima Ismailovim koji su živeli u Paranu da prihvate Toru.\" Raši, uz Ponovljeni zakon 33:2.","headingId":"rasijevo-tumacenje","headingText":"Rašijevo tumačenje"}]},{"slug":"Kovceg-zaveta-i-Kaba","chunks":[{"text":"Kovčeg zaveta imao je kod Jevreja položaj sličan onome koji Časna Kaba i Crni kamen imaju kod muslimana. Ploče u Kovčegu bile su od Uzvišenog Allaha i nisu bile nešto prirodno, niti obično kamenje, niti ljudsko delo. Među rabinima i danas postoje neslaganja o samom Kovčegu, o njegovom sadržaju i o tome gde se on sada nalazi. Naslov izvornog teksta tvrdi da zidovi Kabe sadrže kamenje iz Kovčega zaveta. Sam tekst, međutim, za tu tvrdnju ne donosi nikakav dokaz, nego izlaže poređenje između Kovčega i Kabe. Zato je ovde prenet taj sadržaj, a tvrdnja iz naslova nije preuzeta kao utvrđena.","headingId":"","headingText":""},{"text":"Kovčeg zaveta Izlazak 25:16 I metni u kovčeg svedočanstvo, koje ću ti dati. Ploče koje su bile u Kovčegu bile su od Uzvišenog Allaha. Nisu bile nešto prirodno, niti obično kamenje, niti ljudsko delo. Jevreji su Kovčeg nosili sa sobom u pobedu nad neprijateljima, a to je bila Allahova blagodat i dobrota prema njima.","headingId":"kovceg-zaveta","headingText":"Kovčeg zaveta"},{"text":"Otvorena pitanja kod samih rabina Među rabinima i danas postoje neslaganja o Kovčegu, o njegovom sadržaju i o tome gde se on sada nalazi. Encyclopedia Biblica, odrednica o Kovčegu zaveta.","headingId":"otvorena-pitanja-kod-samih-rabina","headingText":"Otvorena pitanja kod samih rabina"},{"text":"Poređenje Kovčeg je kod Jevreja imao veliki položaj, sličan onome koji Časna Kaba i Crni kamen imaju kod muslimana. Oba su, u svojim zajednicama, predstavljala znak Božije naklonosti.","headingId":"poredjenje","headingText":"Poređenje"}]},{"slug":"Meka-i-Jesrib-u-Bibliji","chunks":[{"text":"Postanje 10:30 spominje naziv Meša, koji se dovodi u vezu sa Mekom. Prevod Biblije iz Njukasla iz 1811. godine to mesto donosi kao „od Meke dok ne dođeš do Medine\". Raši, ugledni jevrejski učenjak, poistovetio je Mišu sa Mekom, a i prevod Saadje Gaona izričito spominje oba grada. Uz to, kumranski rukopis iz četvrte pećine opisuje budući Dom Božiji u koji stranci neće ući i u kojem je borba zabranjena.","headingId":"","headingText":""},{"text":"Postanje 10:30 Postanje 10:30 I življahu od Mese, kako se ide na Sefar do gore istočne. Naziv Meša, odnosno Masa, dovodi se u vezu sa Mekom. Prevod Biblije iz Njukasla iz 1811. godine to mesto donosi ovako: A njihovo prebivalište bilo je od Meke dok ne dođeš do Medine, prema istočnoj gori. Izvor: Biblija iz Njukasla, 1811. Newcastle Bible, 1811. Raši, ugledni jevrejski učenjak, poistovetio je Mišu sa Mekom. Raši. I prevod Saadje Gaona izričito spominje oba grada. Saadja Gaon, prevod Tore. Masa je, uz to, i ime jednog Ibrahimovog potomka preko njegovog sina Ismaila, koji je živeo u istočnom delu Arapskog poluostrva.","headingId":"postanje-1030","headingText":"Postanje 10:30"},{"text":"Kumranski midraš o poslednjim danima Rukopis iz četvrte kumranske pećine, iz prvog veka pre nove ere, opisuje budući Dom Božiji sa određenim odlikama: 1. U njega može ući samo obrezani narod. 2. Stranci u njega neće ući niti će ga razoriti. 3. Borba je u njemu zabranjena. 4. Nered je u njemu zabranjen. Rukopis to proročanstvo povezuje sa Izlaskom 15:17 18. Kumran, četvrta pećina, midraš o poslednjim danima.","headingId":"kumranski-midras-o-poslednjim-danima","headingText":"Kumranski midraš o poslednjim danima"},{"text":"Dodatna napomena Seid ibn Batrik u svom komentaru iz 1773. godine navodi: Hadžera je uzela svog sina i otišla, pa se nastanila u gradu koji se zove Jesrib. Reč je o predelu Hidžaza, gde se Ismail kasnije oženio i gde je bio ukopan. Seid ibn Batrik, komentar iz 1773.","headingId":"dodatna-napomena","headingText":"Dodatna napomena"}]},{"slug":"Mojsijev-zavet-i-racun-godina","chunks":[{"text":"Mojsijev zavet spada u apokrifne spise. Njegov rukopis potiče iz šestog veka, a napisan je na latinskom, prema hebrejskom ili aramejskom izvorniku iz prvog veka. Rukopis je pronađen u Milanu 1861. godine, nakon što je vekovima bio nepoznat. Račun od 250 puta sedam, dakle 1750 godina, dodat na vreme Musaove smrti oko 1183. godine pre nove ere, vodi u razdoblje između 567. i 574. godine.","headingId":"","headingText":""},{"text":"O samom spisu Mojsijev zavet spada u apokrifne spise, dakle u knjige koje nisu uvrštene u kanon. Njegov rukopis potiče iz šestog veka nove ere, što znači da je više od trinaest vekova ostao nepoznat. Napisan je na latinskom jeziku, prema hebrejskom ili aramejskom izvorniku iz prvog veka nove ere. Istraživači smatraju da je pripadao jevrejskoj sekti esena.","headingId":"o-samom-spisu","headingText":"O samom spisu"},{"text":"Okolnosti nalaza Snaga tog argumenta leži u tome što je rukopis pronađen u Milanu 1861. godine i što je pre toga vekovima bio nepoznat. To je bitno zato što isključuje mogućnost da je tekst naknadno prilagođen. Ako je rukopis stotinama godina bio izvan domašaja i pronađen tek u devetnaestom veku, nije mogao biti podešen prema kasnijim događajima.","headingId":"okolnosti-nalaza","headingText":"Okolnosti nalaza"},{"text":"Račun godina Račun glasi: 250 puta sedam, dakle 1750 godina. Musa je, prema tom računu, umro oko 1183. godine pre nove ere. Dodavanjem 1750 godina dobija se razdoblje između 567. i 574. godine nove ere. Poznato je da je poslanik Muhammed ﷺ rođen 570. godine. Račun počiva na datovanju Musaove smrti, oko kojeg među istoričarima ne postoji saglasnost, kao i na određenom tumačenju samog broja iz teksta. Snaga argumenta, dakle, zavisi od prihvatanja tih polazišta.","headingId":"racun-godina","headingText":"Račun godina"}]},{"slug":"Osija-9-6-i-rec-mahmad","chunks":[{"text":"U nevokalizovanom hebrejskom tekstu Osije 9:6 javlja se četvoroslovni oblik mem het mem dalet, koji se može čitati i kao vlastito ime i kao pridev u značenju dragocenost. Septuaginta ga prenosi kao Mahmas, dakle kao vlastito ime, što Pulpit Commentary objašnjava time da su ga prevodioci uzeli za lično ime. Gezenijus u svojoj gramatici preporučuje čitanje mahmadi kaspam.","headingId":"","headingText":""},{"text":"Nevokalizovani hebrejski tekst Nevokalizovani hebrejski tekst Osije 9:6 glasi: כי הנה הלכו משד מצרים תקבצם מף תקברם מחמד לכספם קמוש יירשם חוח באהליהם U središtu pažnje je četvoroslovni oblik מחמד, dakle mem het mem dalet, koji se može čitati na dva načina: kao vlastito ime ili kao pridev mahmad, u značenju dragocenost. Hebrejski tekst izvorno se pisao bez samoglasnika. Sistem vokalizacije uveden je vekovima kasnije, pa izbor između ta dva čitanja nije dat u samom izvornom tekstu, nego je stvar naknadne odluke.","headingId":"nevokalizovani-hebrejski-tekst","headingText":"Nevokalizovani hebrejski tekst"},{"text":"Obrazac imena i sudbine Ajet je ustrojen kao niz kaznenih jedinica koje slede obrazac ime i sudbina. Dosledna struktura tog niza ide u prilog čitanju tog oblika kao imena, a ne kao prideva.","headingId":"obrazac-imena-i-sudbine","headingText":"Obrazac imena i sudbine"},{"text":"Gezenijusova gramatika Gezenijus u svojoj hebrejskoj gramatici preporučuje čitanje מחמדי כספם, odnosno mahmadi kaspam, u značenju „Muhammed za njihovo srebro\", to jest za njihov imetak. Gesenius, hebrejska gramatika.","headingId":"gezenijusova-gramatika","headingText":"Gezenijusova gramatika"},{"text":"Svedočanstvo Septuaginte Septuaginta tu reč prenosi kao Μαχμάς, odnosno Mahmas. Pulpit Commentary to objašnjava rečima da su prevodioci tu reč pogrešno uzeli za vlastito ime. The Pulpit Commentary, uz Osiju 9:6. Sama činjenica da su prevodioci Septuaginte, koji su radili pre nove ere, taj oblik preneli kao ime, pokazuje da čitanje u obliku imena nije naknadna domišljatost, nego jedno od najstarijih zabeleženih razumevanja tog mesta.","headingId":"svedocanstvo-septuaginte","headingText":"Svedočanstvo Septuaginte"},{"text":"Povezivanje sa pohodom na Benu Nadir To se povezuje sa pohodom na Benu Nadir, uz upućivanje na Kur'an i na Sahih Buharije. Sura El Hašr 59:6 A vi niste, radi onoga što je Allah od njih, kao plen, Svome Poslaniku dao, ni konja ni kamila potjerali. Sahih Buhari, 4885.","headingId":"povezivanje-sa-pohodom-na-benu-nadir","headingText":"Povezivanje sa pohodom na Benu Nadir"}]},{"slug":"Parakletos-u-Jovanu-16","chunks":[{"text":"Grčki oblik parakletos znači utešitelj ili zagovornik, dok periklitos znači najhvaljeniji, što odgovara imenu Ahmed. Karen Armstrong potvrđuje da je sirijski prevod glasio Munahhema, glasovno blisko imenu Muhammed, i da se oblik Periklitos koristio među arapskim hrišćanima. U Jovanu se koristi reč alos, koja označava drugog iste vrste, a ne heteros, koja bi značila drugačijeg.","headingId":"","headingText":""},{"text":"Dva grčka čitanja 1. Parakletos , παράκλητος, u značenju utešitelj, zagovornik, pomagač. 2. Periklitos , περικλυτός, u značenju najhvaljeniji, slavni. Kroz niz istoznačnica, gde kletos odgovara obliku endoksos, a taj obliku mahmud, dolazi se do toga da je taj oblik tačan prevod imena Ahmed.","headingId":"dva-grcka-citanja","headingText":"Dva grčka čitanja"},{"text":"Svedočanstva istraživača Rejmond E. Braun u Anchor Bible prepoznao je da se Paraklet može odnositi na ljudsku osobu, a ne nužno na Svetog Duha. Raymond E. Brown, Anchor Bible. Karen Armstrong potvrdila je da je sirijski prevod glasio Munahhema, što je glasovno blisko imenu Muhammed, i navela da se oblik Periklitos koristio među arapskim hrišćanima. Karen Armstrong. Abdul Ahad Davud, nekadašnji haldejski katolički sveštenik, naveo je da to predstavlja jedan od najjačih dokaza Muhammedovog ﷺ poslanstva, i to na osnovu grčke etimologije. Abdul Ahad Dawud, Muhammad in the Bible.","headingId":"svedocanstva-istrazivaca","headingText":"Svedočanstva istraživača"},{"text":"Unutrašnje napetosti u hrišćanskom tumačenju Jovan 16:7 Jer ako ja ne odem, Utešitelj neće doći k vama; ako li odem, poslaću ga k vama. Jovan 20:22 I ovo rekavši dunu i reče im: Primite Duh Sveti. Prvi tekst navodi da Paraklet dolazi tek nakon Isaovog odlaska, a drugi prikazuje kako Isa daje Duha pre uzdignuća. Ta napetost priznata je i u samoj hrišćanskoj literaturi. 1. Jovanova 2:1 Imamo zastupnika kod Oca, Isusa Hrista pravednika. Ovde se sam Isa naziva parakletom. Budući da se u Jovanu koristi reč alos, ἄλλος, koja označava drugog iste vrste, a ne heteros, ἕτερος, koja bi označavala drugačijeg, sledi da bi taj drugi Paraklet trebalo da bude čovek.","headingId":"unutrasnje-napetosti-u-hriscanskom-tumacenju","headingText":"Unutrašnje napetosti u hrišćanskom tumačenju"},{"text":"Istorijski pretendenti Montan u drugom veku i Mani Persijanac u trećem veku obojica su tvrdili da su Paraklet, što pokazuje da je u ranom hrišćanstvu postojalo očekivanje ljudskog poslaničkog lika, a ne samo duha.","headingId":"istorijski-pretendenti","headingText":"Istorijski pretendenti"},{"text":"Pitanje rukopisnog prenosa Izvorni rukopisi Jevanđelja ne postoje. Najstariji ulomci potiču sa kraja drugog i iz trećeg veka, a potpuni rukopisi tek iz četvrtog veka. Rani prepisivači nisu bili stručnjaci i nisu nužno bili obavezni da tekst prenesu u tačnom redosledu reči. Treba biti jasan: nijedan sačuvani grčki rukopis Jovana 14 16 ne sadrži oblik Periklitos. Argument počiva na jezičkoj rekonstrukciji i na istoriji prevoda, a ne na neposrednoj rukopisnoj potvrdi.","headingId":"pitanje-rukopisnog-prenosa","headingText":"Pitanje rukopisnog prenosa"},{"text":"Kur'anska preciznost Sura Es Saff 61:6 I kada Isa, sin Merjemin, reče: O sinovi Israilovi, ja sam vam Allahov poslanik da vam potvrdim pre mene objavljeni Tevrat i da vam donesem radosnu vest o poslaniku čije je ime Ahmed, koji će posle mene doći. Kur'an navodi ime Ahmed, koje je u superlativnom obliku i znači najhvaljeniji, a ne Muhammed, koji je u prostom obliku i znači hvaljeni. Taj superlativni oblik odgovara ustrojstvu grčkog oblika Periklitos.","headingId":"kuranska-preciznost","headingText":"Kur'anska preciznost"}]},{"slug":"Ponovljeni-zakon-18-18","chunks":[{"text":"Proročanstvo postavlja četiri uslova: da će to biti poslanik, a ne bog niti bogočovek; da će biti između braće sinova Israilovih, dakle ne iz samih sinova Israilovih; da će biti poput Musaa; i da će mu Bog Svoje reči staviti u usta, što znači da će primati neposrednu objavu. Ograničavajuća odredba „između vas\", koja bi proročanstvo svela na Israilćane, izostaje u Septuaginti, samarićanskom Petoknjižju, rukopisima Ponovljenog zakona sa Mrtvog mora i u navodu u Delima apostolskim.","headingId":"","headingText":""},{"text":"Tekst proročanstva Ponovljeni zakon 18:15 18 Gospod Bog tvoj podignuće ti proroka između braće tvoje, kao što sam ja, njega slušajte… Podignuću im proroka između braće njihove, kao što si ti, i metnuću reči svoje u usta njegova, i kazivaće im sve što mu zapovedim.","headingId":"tekst-prorocanstva","headingText":"Tekst proročanstva"},{"text":"Četiri uslova 1. Biće poslanik, a ne bog niti bogočovek. 2. Biće između braće sinova Israilovih, dakle ne iz samih sinova Israilovih. 3. Biće poput Musaa. 4. Bog će mu Svoje reči staviti u usta, što znači da će primati neposrednu objavu.","headingId":"cetiri-uslova","headingText":"Četiri uslova"},{"text":"Ko su braća sinova Israilovih Postanje 25:18 I nastaniše se među svom braćom svojom. Postanje 16:12 I nastaniće se prema svoj braći svojoj. I Edomci se u Bibliji nazivaju braćom, iako su rođaci, a ne potomci Israilovi: Ponovljeni zakon 23:7 Nemoj se gaditi na Edomca, jer ti je brat. Majmonid je priznao da se izraz „između braće tvoje\" prirodno odnosi na Isava i Ismaila, bez dodatnih ograda, i da je potreban poseban argument da bi se svelo samo na Israilćane. Majmonid.","headingId":"ko-su-braca-sinova-israilovih","headingText":"Ko su braća sinova Israilovih"},{"text":"Rukopisno pitanje Odredba „između vas\", koja bi proročanstvo ograničila na Israilćane, ne javlja se u Septuaginti, samarićanskom Petoknjižju, rukopisima Ponovljenog zakona sa Mrtvog mora, ni u navodu u Delima apostolskim. Ona se javlja isključivo u masoretskom tekstu.","headingId":"rukopisno-pitanje","headingText":"Rukopisno pitanje"},{"text":"Samarićansko Petoknjižje I neće se više podići u Israilu prorok poput Musaa. Reč je o trajnoj negaciji u budućnosti, za razliku od masoretske konstrukcije u prošlom vremenu: Ponovljeni zakon 34:10 I ne usta više prorok u Izrailju kao Mojsije.","headingId":"samaricansko-petoknjizje","headingText":"Samarićansko Petoknjižje"},{"text":"Ocena katoličkog sveštenika Otac Pol el Fegali primetio je da je čitanje zasnovano na doslovnom tumačenju pokazalo da Isus ne može biti poslanik kojeg je Musa najavio, i to zbog nepodudaranja sa samim uslovima proročanstva. Otac Pol el Fegali.","headingId":"ocena-katolickog-svestenika","headingText":"Ocena katoličkog sveštenika"},{"text":"Istorijska jevrejska svedočanstva Ibn Hišam u svojoj Siri beleži kazivanje o jevrejskom susedu koji je govorio da će doći poslanik iz ovih krajeva, pokazujući ka Meki i Jemenu. Ibn Hišam, Sira. Teofan je zabeležio da je deset jevrejskih prvaka isprva prihvatilo Muhammedovo ﷺ poslanstvo, verujući da je on očekivani Mesija. Teofan Ispovednik, Hronografija.","headingId":"istorijska-jevrejska-svedocanstva","headingText":"Istorijska jevrejska svedočanstva"}]},{"slug":"Ponovljeni-zakon-18-20-i-lazni-poslanici","chunks":[{"text":"Ponovljeni zakon 18:20 postavlja merilo: poslanik koji govori u Božije ime ono što mu nije naređeno, umreće. To se razume tako da lažni poslanik biva ubijen ili umire pre nego što dovrši svoju misiju. Primenjeno na poznate pretendente, merilo daje dosledan ishod, dok je poslanica Muhammeda ﷺ dovršena, što potvrđuje ajet o upotpunjenju vere.","headingId":"","headingText":""},{"text":"Merilo Ponovljeni zakon 18:20 Ali prorok koji bi se usudio govoriti šta u moje ime što mu ja ne zapovedim da govori, ili koji bi govorio u ime drugih bogova, takav prorok da se pogubi. To se razume tako da lažni poslanik biva ubijen ili umire pre nego što dovrši svoju misiju.","headingId":"merilo","headingText":"Merilo"},{"text":"Jovan Krstitelj Jovan Krstitelj nije tvrdio da je on očekivani poslanik, nego je iščekivao dolazak drugoga. Matej 11:3 Jesi li ti onaj što će doći, ili drugoga da čekamo?","headingId":"jovan-krstitelj","headingText":"Jovan Krstitelj"},{"text":"Isa, mir neka je na njega Ako se to proročanstvo primeni na Isaa, uz hrišćansko verovanje da je ubijen, onda bi po tom merilu ispao lažan. Muslimani, međutim, ne prihvataju da je Isa ubijen. Kur'an navodi da nije ni ubijen ni raspet, nego da je uzdignut Allahu. Ovaj argument, dakle, pogađa hrišćansko shvatanje, a ne muslimansko.","headingId":"isa-mir-neka-je-na-njega","headingText":"Isa, mir neka je na njega"},{"text":"Muhammed ﷺ Njegova poslanica dovršena je u najpotpunijem obliku, što potvrđuje i objava: Sura El Maida 5:3 Sada sam vam veru vašu usavršio i blagodat Svoju prema vama upotpunio i zadovoljan sam da vam islam bude vera.","headingId":"muhammed-","headingText":"Muhammed ﷺ"},{"text":"Poznati pretendenti i njihov ishod 1. Musejlema ubijen u Bici na Jemami. 2. El Esved el Ansi ubijen u svom dvorcu. 3. Mirza Gulam Kadijani umro u neočekivanim okolnostima nakon jedne verske rasprave. 4. Bab zatvoren, a zatim pogubljen. 5. Rašad Halifa ubijen od strane bliskih saradnika.","headingId":"poznati-pretendenti-i-njihov-ishod","headingText":"Poznati pretendenti i njihov ishod"}]},{"slug":"Ponovljeni-zakon-33-2-i-Paran","chunks":[{"text":"Ponovljeni zakon 33:2 spominje tri mesta: Sinaj, Seir i Paran. Masoretski tekst na jednom mestu ima oblik ואתה, dok samarićanski, Septuaginta, Vulgata, targumi i sirijski imaju ואתו. Sama jevrejska predanja, Midraš Tanhuma, Targum Jonatan i Raši, Paran izričito vezuju za sinove Ismailove, a Seir za sinove Isavove.","headingId":"","headingText":""},{"text":"Tekst Ponovljeni zakon 33:2 Gospod izađe sa Sinaja, i pokaza im se sa Seira; zasja s gore Faranske. Avakum 3:3 Bog dođe od Temana i Svetac s gore Farana.","headingId":"tekst","headingText":"Tekst"},{"text":"Rukopisna razlika Masoretski tekst na jednom mestu ima oblik ואתה, u čitanju kao „dođe\", dok samarićanski tekst, Septuaginta, Vulgata, targumi i sirijski prevod imaju ואתו, u čitanju „s njim\". Svi drevni tekstovi, dakle samarićanski, grčki, latinski, aramejski i sirijski, na tom mestu odstupaju od hebrejskog masoretskog teksta.","headingId":"rukopisna-razlika","headingText":"Rukopisna razlika"},{"text":"Gde je Paran Postanje 21:21 A on življaše u pustinji Faranu. Postanje 25:12 18 A življahu od Evila do Sura prema Egiptu. Naziv Paran u Bibliji nema jedno jedino mesto. U Brojevima se smešta na Sinajsko poluostrvo, u predeo Vadi Fejrana, dok ga Ponovljeni zakon 1:1 smešta istočno od Jordana. Adam Klark u svom komentaru navodi da Paran leži na samim granicama Obećane zemlje, na ogromnoj udaljenosti od prethodno spomenutog mesta. Adam Clarke, komentar Biblije. Sam izvorni tekst priznaje da tu postoji zabuna. Enciklopedija Biblika navodi da nije lako razumeti sva starozavetna mesta koja se odnose na Paran. Uz to, 1. Samuilova 25:1 spominje Paran, dok Septuaginta na istom mestu ima Maon, što ukazuje na oštećenje teksta.","headingId":"gde-je-paran","headingText":"Gde je Paran"},{"text":"Jevrejska predanja Sveti je ponudio Toru svim narodima… Seir se odnosi na sinove Isavove, a gora Paran na sinove Ismailove. Izvor: Midraš Tanhuma. Midraš Tanhuma. Targum Jonatan navodi da je Bog Zakon ponudio sinovima Ismailovim kod Parana, ali da ga oni nisu prihvatili. Targum Jonatan. Raši, uz Avakuma 3:3, navodi: „Ponudio si ga Isavu i Ismailu, i oni ga nisu prihvatili.\" Raši, uz Avakuma 3:3. Značaj tih predanja je u tome što ne dolaze iz muslimanskih izvora. Sama jevrejska tradicija Paran vezuje za Ismaila i njegovo potomstvo, nezavisno od bilo kakvog islamskog tumačenja.","headingId":"jevrejska-predanja","headingText":"Jevrejska predanja"},{"text":"Pitanje glagolskog vremena Prigovor da je glagol u prošlom vremenu, pa da se ne može odnositi na budućnost, ne stoji, jer se proročanstva u hebrejskom redovno izriču u prošlom vremenu. Isaija 53:7 Mučen bi i zlostavljen, ali ne otvori usta svojih. I to je proročanstvo izrečeno u prošlom vremenu, iako se odnosi na budućnost.","headingId":"pitanje-glagolskog-vremena","headingText":"Pitanje glagolskog vremena"},{"text":"Prevodilačka nedoslednost U pojedinim arapskim prevodima hebrejska množina עַמִּים, dakle narodi, prevedena je jedninom, kao narod, čime se prikriva šira primenljivost teksta izvan Israila.","headingId":"prevodilacka-nedoslednost","headingText":"Prevodilačka nedoslednost"}]},{"slug":"Psalam-120-i-satori-Kedarovi","chunks":[{"text":"Aramejski targum uz Psalam 120 naziv Kedar zamenjuje izrazom „šatori Arapa\", čime sama drevna jevrejska tumačiteljska tradicija Kedar razume etnički, kao Arape. Hebrejski oblik mešeh može označavati i trajanje, a ne nužno naziv mesta, jer hebrejski izvorno nije imao samoglasničke oznake. Tako se peti stih može čitati kao „dugo sam boravio\", što psalam čini opisom dugotrajnog progona.","headingId":"","headingText":""},{"text":"Tekst Psalam 120:5 7 Teško meni kad sam tuđin u Mesehu, živim među šatorima Kidarskim. Dugo živi duša moja s onima koji mrze mir. Ja sam miran, ali kad progovorim, oni su na rat.","headingId":"tekst","headingText":"Tekst"},{"text":"Kedar kao Arapi Aramejski targum uz Psalam 120 naziv Kedar zamenjuje izrazom „šatori Arapa\". Aramejski targum uz Psalme. To pokazuje da je drevna jevrejska tumačiteljska tradicija Kedar razumela etnički, kao Arape, a ne samo simbolički.","headingId":"kedar-kao-arapi","headingText":"Kedar kao Arapi"},{"text":"Rukopisna svedočanstva Arapsko latinsko svedočanstvo Psalama u delu David Regis et Prophetae, koje je priredio J. J. L. Barže 1861. godine, čuva tekst: „Teško meni što dugo boravim… i živim u šatorima Kedarovim.\" David Regis et Prophetae, prir. J. J. L. Bargès, 1861. Arapski hrišćanski psaltir bazilijanske crkve iz 1871. godine čuva oblik: „Boravio sam u staništima, odnosno šatorima Kedarovim.\" Bazilijanski psaltir, 1871.","headingId":"rukopisna-svedocanstva","headingText":"Rukopisna svedočanstva"},{"text":"O reči mešeh Hebrejski oblik משך, mešeh, može označavati trajanje ili dugo razdoblje, a ne nužno naziv mesta. Hebrejski jezik izvorno nije imao samoglasničke oznake, a masoretska vokalizacija uvedena je znatno kasnije. Bez vokalizacije, peti stih može se čitati kao „dugo sam boravio\", umesto „boravim u Mesehu\".","headingId":"o-reci-meseh","headingText":"O reči mešeh"},{"text":"Čitanje psalma Tako se psalam čita kao opis dugotrajnog tlačenja u Meki, boravka među Kurejšijama, odnosno Kedarom, i položaja vernika koji su mirni, a kojima se odgovara ratom, dakle stanja muslimana pre Hidžre.","headingId":"citanje-psalma","headingText":"Čitanje psalma"},{"text":"O Majmonidovom tumačenju Majmonid je u svom pismu Jemenu taj psalam primenio na jevrejsko stradanje pod muslimanskom vlašću, navodeći: „Teško meni što živim sa Mesehom i među šatorima Kedarovim.\" Majmonid, Pismo Jemenu. Na to se odgovara pitanjem: ako Kedar označava Kurejšije i Arape, da li su Jevreji doslovno živeli među mekanskim šatorima? Psalam, dakle, opisuje muslimane koji stradaju među Kurejšijama pre Hidžre.","headingId":"o-majmonidovom-tumacenju","headingText":"O Majmonidovom tumačenju"}]},{"slug":"Psalam-72-i-narod-Sabe","chunks":[{"text":"Hebrejski naziv Šeba u Psalmu 72 rečnici određuju kao narod i oblast Srećne Arabije, a niz arapskih hrišćanskih rukopisa, od jedanaestog do osamnaestog veka, to mesto prevodi izrazom Arapi. Metju Henri priznaje da se mnoga mesta u tom psalmu ne mogu primeniti na Sulejmanovu vladavinu.","headingId":"","headingText":""},{"text":"Tekst Psalam 72:10 11 Carevi Tarsiski i ostrvljani doneće dare, carevi Šavski i Savski daće danak. Klanjaće mu se svi carevi, svi narodi biće mu pokorni. Psalam 72:17 Ime će njegovo ostati doveka; dokle traje sunce, ime će se njegovo množiti. I blagosiljaće se u njemu, svi ga narodi zvati blaženim.","headingId":"tekst","headingText":"Tekst"},{"text":"Ko su narodi Šebe Brown Driver Briggsov hebrejski rečnik Šebu određuje kao narod i oblast Srećne Arabije. Brown Driver Briggs Hebrew Lexicon, odrednica Šeba. Isto navodi i Gezenijusov hebrejsko haldejski rečnik. Gesenius' Hebrew Chaldee Lexicon. Na to upućuje i rečnička odrednica uz izdanje JPS iz 1985. godine. JPS 1985, Sefaria.","headingId":"ko-su-narodi-sebe","headingText":"Ko su narodi Šebe"},{"text":"Arapski hrišćanski rukopisi Niz arapskih hrišćanskih rukopisa, koji se prostiru od jedanaestog do osamnaestog veka, hebrejski naziv Šeba dosledno prenosi izrazom العرب, dakle Arapi. Treba biti precizan: rečnici Šebu određuju kao narod i oblast, a ne kao jednu osobu. Ono što ti rukopisi pokazuju jeste da su rani hrišćanski čitaoci to mesto razumeli kao upućivanje na Arape, a ne da u samom tekstu stoji lično ime.","headingId":"arapski-hriscanski-rukopisi","headingText":"Arapski hrišćanski rukopisi"},{"text":"Šta kažu hrišćanski komentatori Metju Henri navodi da se mnoga mesta u tom psalmu ne mogu primeniti na Sulejmanovu vladavinu. Matthew Henry, komentar Psalama.","headingId":"sta-kazu-hriscanski-komentatori","headingText":"Šta kažu hrišćanski komentatori"},{"text":"Zašto to ne može biti Sulejman Psalam govori o vladavini koja traje dokle traje sunce, o pokornosti svih naroda i o imenu koje se množi kroz sva vremena, što prevazilazi okvire jedne istorijske vladavine.","headingId":"zasto-to-ne-moze-biti-sulejman","headingText":"Zašto to ne može biti Sulejman"},{"text":"Ime koje se blagosilja Ime koje se u psalmu spominje i koje se množi dovodi se u vezu sa korenom u značenju hvaljen, od kojeg dolazi i ime Muhammed, u značenju hvaljeni.","headingId":"ime-koje-se-blagosilja","headingText":"Ime koje se blagosilja"}]},{"slug":"Psalam-84-i-Bekka","chunks":[{"text":"Više drevnih prevoda Psalma 84 to mesto donosi tako da povezuje Bekku sa tri postojana elementa: sa određenim čovekom koji je u njoj rođen i u njoj boravi, sa davanjem novog Zakona, i sa davanjem blagoslova. Kirkpatrik u svom komentaru napominje da reč baka potiče od korena koji znači plakati, ali da nigde u Bibliji ne znači plakanje, te da balzamovo drveće obilno raste u sušnoj mekanskoj dolini.","headingId":"","headingText":""},{"text":"Tekst Psalam 84:5 6 Blago onima kojima je sila u Tebi… Prolazeći dolinom plača pretvaraju je u izvore.","headingId":"tekst","headingText":"Tekst"},{"text":"Drevni prevodi 1. Koptsko arapski prevod Psalama: „Blago čoveku koji se u Tebe uzda, Gospode; Zakonodavac daje blagoslove svojim sledbenicima.\" 2. Prevod Psalama sa teksta Septuaginte, 1954: „Blago čoveku kojem Ti pomažeš, koji je odlučio da se popne u dolinu Baka; penje se ka mestu koje dobro poznaje i koje namerava; na tom mestu Sudija, Bog, daje mu blagoslov.\" 3. Prevod jezuitskih otaca, 1897: „Prolaze dolinom plača i čine je mestom izvora. Jer Zakonodavac ih obasipa svojim blagoslovima.\" 4. Prevod Starog zaveta, 1811: „Blago čoveku kojeg si Ti izbavio od Sebe, koji je Božije zakone stavio u svoje srce. Rođen je u dubini Bekke, i tu je bilo njegovo boravište; tu uspostavlja novi Zakon.\" 5. Verzija Dejvida Tomasa: „Blago čoveku","headingId":"drevni-prevodi","headingText":"Drevni prevodi"},{"text":"koji se u Tebe uzda, kojeg si Ti izbavio od Sebe. Ti si ga, Bože, smestio u Bekku; u Bekki on uspostavlja Zakon.\" 6. Verzija Ibn el Assala: „Blago čoveku kojeg si Ti izbavio od Sebe, koji je Tvoje zakone stavio u svoje srce. Rođen je u Bekki, i ona je bila njegovo boravište; tu daje Zakon i blagoslove.\" Svaki drevni prevod, dakle, Bekku povezuje sa tri postojana elementa: sa određenim čovekom koji je u njoj rođen i u njoj boravi, sa davanjem novog Zakona, i sa davanjem blagoslova. Van Dajkov arapski prevod tu osobu potpuno izostavlja, iako je svaki stariji prevod čuva.","headingId":"drevni-prevodi","headingText":"Drevni prevodi"},{"text":"Kirkpatrikov komentar Baka potiče od korena koji znači plakati, ali nigde u Bibliji ne znači plakanje, jer se za to koriste reči drugog oblika. Za balzamovo drveće se kaže da voli suva staništa, pa tako obilno raste, na primer, u sušnoj dolini Meke. Izvor: A. F. Kirkpatrik. A. F. Kirkpatrick, The Book of Psalms: Introduction and Notes, tom 2, str. 507.","headingId":"kirkpatrikov-komentar","headingText":"Kirkpatrikov komentar"},{"text":"Kur'anska mesta Sura Ali Imran 3:96 Prvi hram sagrađen za ljude jeste onaj u Bekki, blagoslovljen je on i putokaz svetovima. Sura Ibrahim 14:37 Gospodaru naš, ja sam neke potomke svoje naselio u kotlini u kojoj se ništa ne seje, kod Tvoga Časnog hrama.","headingId":"kuranska-mesta","headingText":"Kur'anska mesta"},{"text":"Svedočanstvo Mudžahida Ja sam Bog Bekke. Smestio sam je između ove dve planine. Oblikovao sam Sunce i Mesec, okružio je sa sedam uspravnih meleka, a opskrbu njenih stanovnika učinio da dolazi sa tri puta, jer se ljudima Meke prilazi samo sa tri puta: gornjom dolinom, donjom dolinom i Kudom. I blagoslovio sam njene stanovnike u mesu i vodi. Izvor: preneseno od Mudžahida, preko Husajfa ibn Abdur Rahmana. Ahbar Mekka, str. 138, izd. Abdul Melik ibn Duhajš, 2003.","headingId":"svedocanstvo-mudzahida","headingText":"Svedočanstvo Mudžahida"},{"text":"Podudarnost sa hadisom Psalam 84:10 Jer je bolji dan u dvorima Tvojim nego hiljada. Namaz u mojoj džamiji bolji je od hiljadu namaza na drugom mestu, osim u Časnoj džamiji. Izvor: Buhari i Muslim. Sahih Buhari, 1190; Sahih Muslim, 1394.","headingId":"podudarnost-sa-hadisom","headingText":"Podudarnost sa hadisom"},{"text":"Pet podudarnosti sa Mekom 1. Naziv Bekka, koji se javlja i u Kur'anu. 2. Položaj između dve planine, Safe i Merve. 3. Izvor vode, Zemzem. 4. Neplodna dolina, kako navodi i Kur'an. 5. Umnožena vrednost namaza na tom mestu.","headingId":"pet-podudarnosti-sa-mekom","headingText":"Pet podudarnosti sa Mekom"},{"text":"Jezička napomena Masoretski tekst na tom mestu ima אדם בטח בך, dok Jerusalimski Talmud ima אדם בוטח בך. Arapski nadimak el Abtahi i hebrejski oblik butah dele isti semitski troslovni koren. El Abtah je šljunkovito korito doline između Meke i Mine.","headingId":"jezicka-napomena","headingText":"Jezička napomena"}]},{"slug":"Rukopisne-razlike-u-Jovanovom-jevandjelju","chunks":[{"text":"U Jovanu 7:52 papirusi 66 i 75, iz drugog veka, imaju određeni član ispred reči poslanik, pa tekst glasi „Poslanik\", a ne „poslanik\". Isto ima i sahidski koptski rukopis. U Jovanu 1:27 izraz „koji je preda mnom postao\" izostaje u papirusima 66 i 75, u Sinajskom, Vatikanskom i Efremovom kodeksu, a prvi put se javlja u aleksandrijskom rukopisu iz petog veka.","headingId":"","headingText":""},{"text":"Jovan 7:52 i određeni član Sinajski i Vatikanski kodeks na tom mestu imaju: „Ispitaj i vidi da prorok iz Galileje ne dolazi.\" Papirusi 66 i 75, iz drugog veka, ispred reči prorok imaju određeni član, ὁ προφήτης, pa tekst glasi „Poslanik\", dakle onaj određeni, očekivani poslanik. Sahidski koptski rukopis to mesto donosi rečima: „Poslanik nije trebalo da dođe iz Galileje.\"","headingId":"jovan-752-i-odredjeni-clan","headingText":"Jovan 7:52 i određeni član"},{"text":"Šta o tome kažu istraživači Brus Meciger i Bart Erman navode da prisustvo određenog člana menja smisao, tako da tekst govori o tome da određeni Poslanik ne dolazi iz Galileje. Bruce Metzger i Bart Ehrman, o tekstualnoj kritici Novog zaveta. Otac Fehim Aziz primećuje da čitanje Jovana 7:52 iz papirusa 66 rešava problem koji je komentatore dugo zbunjivao. Otac Fehim Aziz. Razlika je značajna zato što bez određenog člana tekst poriče da iz Galileje dolazi bilo koji poslanik, što je istorijski netačno, jer su iz tog kraja bili i raniji poslanici. Sa određenim članom, tekst govori o jednom određenom očekivanom Poslaniku, čime taj problem nestaje.","headingId":"sta-o-tome-kazu-istrazivaci","headingText":"Šta o tome kažu istraživači"},{"text":"Jovan 1:27 i naknadni dodatak Izraz „koji je preda mnom postao\", ὃς ἔμπροσθέν μου γέγονεν, ne javlja se u sledećim rukopisima: 1. Papirus 66 2. Papirus 75 3. Sinajski kodeks 4. Vatikanski kodeks 5. Efremov kodeks Taj dodatak prvi put se javlja u aleksandrijskom rukopisu iz petog veka. Kritička izdanja Nestle Aland, Vestkot Hort i UBS taj dodatak izostavljaju, i to upravo na osnovu najstarijih rukopisa. Nestle Aland; Westcott Hort; UBS Greek New Testament.","headingId":"jovan-127-i-naknadni-dodatak","headingText":"Jovan 1:27 i naknadni dodatak"},{"text":"Svedočanstvo iz drugog veka Dionisije Korintski, u drugom veku, žali se da prepisivači brišu i dodaju stvari u tekstovima Pisma. Dionisije Korintski.","headingId":"svedocanstvo-iz-drugog-veka","headingText":"Svedočanstvo iz drugog veka"}]},{"slug":"Stara-karta-gore-Paran","chunks":[{"text":"Maleova ručno crtana karta Arabije, objavljena u Parizu 1685. godine, planine Paran smešta neposredno uz Medinu. Strongov hebrejski rečnik Paran određuje kao pustinju Arabije. Ibn Ezra pustinju u kojoj je Ismail živeo poistovećuje sa Arapskim poluostrvom, a bunar iz Postanja 16 sa Zemzemom.","headingId":"","headingText":""},{"text":"Tekst Ponovljeni zakon 33:2 Gospod izađe sa Sinaja, i pokaza im se sa Seira; zasja s gore Faranske, i dođe s mnoštvom hiljada svetaca. Uobičajena hrišćanska tvrdnja jeste da se Paran nalazi u Palestini.","headingId":"tekst","headingText":"Tekst"},{"text":"Kartografsko svedočanstvo Ručno crtana karta Arabije koju je Male objavio u Parizu 1685. godine prikazuje Arapsko poluostrvo sa oznakom „planine Paran\" neposredno uz Medinu. Alain Manesson Mallet, karta Arabije, Pariz, 1685. Poređenje sa savremenom kartom Saudijske Arabije potvrđuje položaj Medine u odnosu na tu istorijsku kartografiju.","headingId":"kartografsko-svedocanstvo","headingText":"Kartografsko svedočanstvo"},{"text":"Rečnička odrednica Strongov hebrejski rečnik Paran određuje kao pustinju Arabije. Strong's Hebrew Dictionary, odrednica Paran.","headingId":"recnicka-odrednica","headingText":"Rečnička odrednica"},{"text":"Jevrejska tumačenja Ibn Ezra, jevrejski tumač Tore, pustinju u kojoj je Ismail živeo poistovetio je sa Arapskim poluostrvom. Ibn Ezra. Saadja Gaon, jevrejski rabin iz desetog veka, mesta koja se odnose na Hadžerin put preveo je izrazom koji upućuje na hidžasko područje, čime se kazivanje vezuje za predeo Meke. Saadja Gaon. Ibn Ezra bunar iz Postanja 16 poistovetio je sa Zemzemom, koji se nalazi kod Meke. Ibn Ezra, uz Postanje 16.","headingId":"jevrejska-tumacenja","headingText":"Jevrejska tumačenja"},{"text":"Postanje 21:21 Postanje 21:21 A on življaše u pustinji Faranu, i mati ga oženi iz zemlje misirske. Ismailovo naselje smešta se, dakle, u Paran, koji se ovde poistovećuje sa Arabijom, u blizini Medine.","headingId":"postanje-2121","headingText":"Postanje 21:21"}]}];
